<?php
use GoldCommerce\{Database,Plugin,Quotes,Rates,Rest,Privacy,ClassicCheckout};
use GoldAgah\Connector;
wp_set_current_user(1);$results=[];
$check=static function($name,$fn)use(&$results){try{$fn();$results[]=['test'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['test'=>$name,'status'=>'FAIL','error'=>$e->getMessage()];}wp_set_current_user(1);};
$assert=static function($value){if(!$value)throw new RuntimeException('Assertion failed');};
$reject=static function($fn)use($assert){$thrown=false;try{$fn();}catch(Throwable $e){$thrown=true;}$assert($thrown);};
$check('SEC.rest_product_schema',static function()use($assert){wp_set_current_user(0);$r=new WP_REST_Request('POST','/gold-commerce/v1/quotes');$r->set_body_params(['product_id'=>18,'quantity'=>1.5,'email'=>'invalid']);$response=rest_do_request($r);$assert($response->get_status()===400);});
$check('SEC.rate_ssrf_and_credentials',static function()use($reject){$reject(fn()=>Rates::http('http://127.0.0.1/'));$reject(fn()=>Rates::addSource('bad','https://127.0.0.1/admin'));$reject(fn()=>Rates::addSource('bad','https://example.test/?api_key=secret'));});
$check('SEC.inbox_scope_and_schema',static function()use($reject){$reject(fn()=>Connector::inbox(['store_uuid'=>'other','company_id'=>'other','event_id'=>'1','schema_version'=>'1']));$reject(fn()=>Connector::inbox(['store_uuid'=>get_option('gc_store_uuid'),'company_id'=>Connector::provider()->company,'event_id'=>'1','schema_version'=>'2']));});
$check('SEC.no_default_guest_admin_access',static function()use($assert){wp_set_current_user(0);foreach(['/gold-commerce/v1/health','/gold-commerce/v1/rates/manual','/gold-commerce/v1/orders/1/issue'] as $path){$r=new WP_REST_Request(str_contains($path,'health')?'GET':'POST',$path);$assert(rest_do_request($r)->get_status()>=400);}});
$check('SEC.audit_chain_and_redaction',static function()use($assert){Database::audit('test.redaction','security',['api_token'=>'HIDDEN-SENTINEL','password'=>'HIDDEN-PASSWORD','safe'=>'ok']);global $wpdb;$row=$wpdb->get_row('SELECT * FROM '.Database::table('security_audit').' ORDER BY id DESC LIMIT 1',ARRAY_A);$assert(!str_contains($row['metadata'],'HIDDEN'));$prev=$wpdb->get_var($wpdb->prepare('SELECT event_hash FROM '.Database::table('security_audit').' WHERE id<%d ORDER BY id DESC LIMIT 1',$row['id']));$assert($row['previous_hash']===$prev);});
$check('SEC.report_role_no_invoice_pii',static function()use($assert){$uid=username_exists('fixture_auditor')?:wp_create_user('fixture_auditor',wp_generate_password(32),'auditor@example.test');$user=new WP_User($uid);$user->set_role('gc_auditor');wp_set_current_user($uid);$assert(current_user_can('gc_view_reports'));$assert(!current_user_can('gc_manage_integrations'));$assert(!current_user_can('gc_issue_quotes'));$orders=wc_get_orders(['status'=>'processing','limit'=>1]);if($orders)$assert(!GoldCommerce\Customer::owns($orders[0]));});
$check('SEC.classic_requires_admin_approval',static function()use($reject){$reject(fn()=>ClassicCheckout::configure(false));wp_set_current_user(0);$reject(fn()=>ClassicCheckout::configure(true));});
$check('SEC.guest_rate_limit',static function()use($assert){$_SERVER['REMOTE_ADDR']='198.51.100.222';$errors=0;for($i=0;$i<35;$i++)if(is_wp_error(Rest::publicAccess()))$errors++;$assert($errors>=5);unset($_SERVER['REMOTE_ADDR']);});
$out=['suite'=>'security','php'=>PHP_VERSION,'at_utc'=>gmdate('c'),'results'=>$results];file_put_contents('/project/evidence/security-php'.PHP_MAJOR_VERSION.PHP_MINOR_VERSION.'.json',wp_json_encode($out,JSON_PRETTY_PRINT));echo wp_json_encode($out,JSON_PRETTY_PRINT);if(array_filter($results,static fn($r)=>$r['status']==='FAIL'))WP_CLI::halt(1);
